    'Empty IN() clause will cause SQL syntax error' => 'Une clause IN() vide provoque une erreur de syntaxe SQL',
    'LIKE with wildcards in SQL - should be parameterized and escaped' => 'LIKE avec des jokers dans le SQL : à paramétrer et à échapper',
    'Parameter placeholders without corresponding setParameter() calls' => 'Des paramètres sans appel à setParameter() correspondant',
