    '<fg=red;options=bold>%d critical</>  <fg=yellow;options=bold>%d %s</>  <fg=blue;options=bold>%d info</>' => '<fg=red;options=bold>critiques : %1$d</>  <fg=yellow;options=bold>avertissements : %2$d</>  <fg=blue;options=bold>info : %4$d</>',
